package vn.smartfarm.iot.control;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.ObjectNode;import java.time.*;import java.util.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.test.web.servlet.MockMvc;import org.springframework.web.server.ResponseStatusException;
import vn.smartfarm.iot.irrigation.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"spring.datasource.url=${SMARTFARM_TEST_DB_URL}","spring.flyway.schemas=telemetry_test","spring.flyway.default-schema=telemetry_test","smartfarm.mqtt.enabled=false","smartfarm.control.enabled=true","smartfarm.control.pump-fencing-enabled=true","smartfarm.control.circuit-route-required=true","smartfarm.irrigation.circuit-demo-enabled=true"})
@AutoConfigureMockMvc @EnabledIfEnvironmentVariable(named="SMARTFARM_TEST_DB_URL",matches=".+")
class PumpCircuitRouteTest {
 @Autowired PumpService pump;@Autowired PumpCommandFencing fencing;@Autowired PumpCircuitProof proof;@Autowired CircuitValveControl valves;@Autowired IrrigationCircuits circuits;@Autowired JdbcTemplate jdbc;@Autowired ObjectMapper mapper;@Autowired MockMvc mvc;
 @MockitoBean CommandTransport transport;@MockitoBean CircuitValveTransport valveTransport;
 UUID boot=UUID.fromString("88000000-0000-4000-8000-000000000001"),vboot=UUID.fromString("88000000-0000-4000-8000-000000000002");PumpCircuitRoute route;
 @BeforeEach void setup()throws Exception{cleanup();jdbc.execute("TRUNCATE pump_command,pump_status,pump_state_history,watering_run,watering_rule");jdbc.update("INSERT INTO watering_rule(singleton) VALUES(1)");reset(transport,valveTransport);when(transport.controlConnected()).thenReturn(true);when(valveTransport.circuitValveConnected(anyString())).thenReturn(true);
  for(int i=1;i<=2;i++){jdbc.update("INSERT INTO iot_node(node_id,name,area_id,node_type,telemetry_version) VALUES(?,?,'AREA001','SOIL',2)","PRSOIL"+i,"Soil");for(int j=1;j<=3;j++)jdbc.update("INSERT INTO iot_channel(node_id,channel_id,metric,unit) VALUES(?,?,'SOIL_MOISTURE','%')","PRSOIL"+i,"SOIL"+j);jdbc.update("INSERT INTO irrigation_zone(zone_id,name,area_id,soil_node_id,expected_source,dry_threshold,wet_threshold) VALUES(?,?,'AREA001',?,'SIMULATOR',30,35)","PRZONE"+i,"Zone","PRSOIL"+i);}
  jdbc.update("INSERT INTO iot_node(node_id,name,area_id,node_type,telemetry_version) VALUES('PRWATER','Water','AREA001','WATER',2)");jdbc.update("INSERT INTO iot_channel(node_id,channel_id,metric,unit) VALUES('PRWATER','LOW','WATER_PRESENT','boolean'),('PRWATER','FLOW','FLOW_RATE','L/min')");
  for(int i=1;i<=2;i++)jdbc.update("INSERT INTO irrigation_circuit(circuit_id,name,zone_id,zone_revision,controller_id,valve_id,pump_id,water_node_id,low_channel_id,flow_channel_id,expected_source) VALUES(?,?,?,1,?,?,'PUMP01','PRWATER','LOW','FLOW','SIMULATOR')","PR"+i,"Circuit","PRZONE"+i,"IRRIGATION"+(77+i),"VALVE"+(77+i));
  route=PumpCircuitRoute.from(circuits.find("PR1"));reportPump(1,0,"OFF",route);reportValve("PR1",1,0,"CLOSED");reportValve("PR2",1,0,"CLOSED");
 }
 @AfterEach void after(){cleanup();jdbc.execute("TRUNCATE pump_command,pump_status,pump_state_history,watering_run,watering_rule");jdbc.update("INSERT INTO watering_rule(singleton) VALUES(1)");}
 void cleanup(){for(String t:List.of("circuit_demo_command","circuit_demo_status","circuit_demo_boot","circuit_demo_gate"))jdbc.update("DELETE FROM "+t+" WHERE valve_id IN ('VALVE78','VALVE79')");jdbc.update("DELETE FROM irrigation_circuit WHERE circuit_id IN ('PR1','PR2')");jdbc.update("DELETE FROM irrigation_zone WHERE zone_id IN ('PRZONE1','PRZONE2')");jdbc.update("DELETE FROM iot_node WHERE node_id IN ('PRSOIL1','PRSOIL2','PRWATER')");}
 ObjectNode pumpPacket(long sequence,long ordinal,String state,PumpCircuitRoute r){var p=mapper.createObjectNode().put("schemaVersion",1).put("deviceId","PUMP01").put("bootId",boot.toString()).put("sequence",sequence).put("timestamp",Instant.now().toString()).put("connection","ONLINE").put("reportedState",state).put("safetyLockout",false).put("stateReason",state.equals("ON")?"COMMAND_ON":"COMMAND_OFF");p.putObject("commandFence").put("version",1).put("lastOrdinal",ordinal).put("restartRequired",false);var f=p.putObject("valveInterlock").put("version",1).put("enabled",true).put("dataSource","SIMULATOR").put("state","OPEN").putNull("fault");if(r!=null)f.set("route",mapper.valueToTree(r));return p;}
 void reportPump(long sequence,long ordinal,String state,PumpCircuitRoute r)throws Exception{pump.receive("smartfarm/FARM001/PUMP01/status",mapper.writeValueAsBytes(pumpPacket(sequence,ordinal,state,r)));}
 ObjectNode valvePacket(String id,long seq,long ordinal,String state){var c=circuits.find(id);var p=mapper.createObjectNode().put("schemaVersion",1).put("controlProfile",CircuitValveControl.PROFILE).put("controllerId",c.controllerId()).put("actuatorId",c.valveId()).put("circuitId",id).put("circuitRevision",c.revision()).put("zoneId",c.zoneId()).put("zoneRevision",c.zoneRevision()).put("bootId",vboot.toString()).put("sequence",seq).put("timestamp",Instant.now().toString()).put("dataSource","SIMULATOR").put("feedbackState",state).put("gpioState",state).put("reason",state.equals("OPEN")?"COMMAND_OPEN":"COMMAND_CLOSE").put("demoEnabled",true).put("lastOrdinal",ordinal);p.putObject("positionFeedback").put("version",1).put("enabled",true).put("state",state).putNull("fault");return p;}
 void valveReceive(String id,ObjectNode p)throws Exception{valves.receive(CircuitValveControl.topic(circuits.find(id).valveId(),p.has("commandId")?"ack":"status"),mapper.writeValueAsBytes(p),false);}
 void reportValve(String id,long seq,long ordinal,String state)throws Exception{valveReceive(id,valvePacket(id,seq,ordinal,state));}
 CircuitValveControl.Request vrequest(String id,String action){var c=circuits.find(id);return new CircuitValveControl.Request(UUID.randomUUID(),action,action.equals("OPEN")?30:null,vboot,c.revision(),c.zoneRevision(),Instant.now());}
 CircuitValveControl.Command openValve()throws Exception{var c=valves.create("PR1",vrequest("PR1","OPEN"));var p=valvePacket("PR1",2,c.ordinal(),"OPEN").put("commandId",c.commandId().toString()).put("ordinal",c.ordinal()).put("action","OPEN").put("result","EXECUTED").putNull("errorCode");valveReceive("PR1",p);reportValve("PR1",3,c.ordinal(),"OPEN");return c;}
 PumpCommandFencing.HttpIntent request(String action,Integer seconds,PumpCircuitRoute r){var v=fencing.view().intent();return new PumpCommandFencing.HttpIntent(UUID.randomUUID(),action,seconds,action.equals("OFF")?null:boot,v.revision(),v.asOf(),r);}
 PumpCommandFencing.Receipt start() {return fencing.createHttp(request("ON",5,route),()->{});}
 long ordinal(UUID id){return jdbc.queryForObject("SELECT fence_ordinal FROM pump_command WHERE command_id=?",Long.class,id);}
 @Test void exactRouteIsTrackedBeforePublishAndDuplicateNeverReplays()throws Exception{openValve();doAnswer(a->{var p=mapper.readTree((byte[])a.getArgument(0));assertEquals(mapper.valueToTree(route),p.path("commandFence").path("route"));assertEquals(route,fencing.lookupHttp(UUID.fromString(p.path("commandId").asText())).request().route());return null;}).when(transport).publishCommand(any());var r=request("ON",5,route);var c=fencing.createHttp(r,()->{});assertEquals("SENT",c.command().state());assertEquals(c,fencing.createHttp(r,()->{}));verify(transport,times(1)).publishCommand(any());assertTrue(fencing.view().ownership().blocked());}
 @Test void genericAndAutomaticOnCannotBypassRoute()throws Exception{openValve();assertThrows(ResponseStatusException.class,()->fencing.createHttp(request("ON",5,null),()->{}));assertThrows(ResponseStatusException.class,()->pump.create(new PumpService.Request("ON",5)));jdbc.update("UPDATE watering_rule SET enabled=true");assertThrows(ResponseStatusException.class,()->fencing.createAutomatic(new PumpService.Request("ON",5),null,id->fail()));verify(transport,never()).publishCommand(any());}
 @Test void absentProofOrRevisionMismatchCannotStart()throws Exception{openValve();var wrong=new PumpCircuitRoute("PR1",2,"PRZONE1",1,"IRRIGATION78","VALVE78");assertThrows(ResponseStatusException.class,()->fencing.createHttp(request("ON",5,wrong),()->{}));jdbc.update("UPDATE irrigation_zone SET revision=2 WHERE zone_id='PRZONE1'");assertThrows(ResponseStatusException.class,this::start);}
 @Test void missingRemoteOpenAckCannotAuthorizePump()throws Exception{var c=valves.create("PR1",vrequest("PR1","OPEN"));reportValve("PR1",3,c.ordinal(),"OPEN");assertEquals("VALVE_COMMAND_UNCONFIRMED",proof.snapshot("PR1").reason());assertThrows(ResponseStatusException.class,this::start);}
 @Test void otherUnknownOrOpenValveBlocksButFreshClosedAllows()throws Exception{openValve();jdbc.update("UPDATE circuit_demo_status SET observed_at=CURRENT_TIMESTAMP-INTERVAL '20 seconds' WHERE valve_id='VALVE79'");assertEquals("OTHER_VALVE_NOT_CLOSED",proof.snapshot("PR1").reason());assertThrows(ResponseStatusException.class,this::start);reportValve("PR2",2,0,"CLOSED");assertTrue(proof.snapshot("PR1").readyToStart());assertEquals("SENT",start().command().state());}
 @Test void pendingOtherValveCommandBlocksEvenWithOldClosedStatus()throws Exception{openValve();valves.create("PR2",vrequest("PR2","OPEN"));assertThrows(ResponseStatusException.class,this::start);}
 @Test void localClosedFaultAndStaleProofBlockStart()throws Exception{openValve();for(String state:List.of("CLOSED","UNKNOWN","CONFLICT")){jdbc.update("UPDATE pump_status SET valve_interlock=jsonb_set(valve_interlock,'{state}',to_jsonb(?::text))",state);assertThrows(ResponseStatusException.class,this::start);}jdbc.update("UPDATE pump_status SET valve_interlock=jsonb_set(valve_interlock,'{state}','\"OPEN\"'),received_at=CURRENT_TIMESTAMP-INTERVAL '20 seconds'");assertThrows(ResponseStatusException.class,this::start);}
 @Test void routeCannotDisappearOrChangeWithinBoot()throws Exception{reportPump(2,0,"OFF",null);assertEquals(1,jdbc.queryForObject("SELECT sequence FROM pump_status",Integer.class));reportPump(3,0,"OFF",PumpCircuitRoute.from(circuits.find("PR2")));assertEquals(route,fencing.view().circuitRoute());assertEquals(1,jdbc.queryForObject("SELECT sequence FROM pump_status",Integer.class));}
 @Test void routeRequiresFencingAndStrictFields()throws Exception{var p=pumpPacket(2,0,"OFF",route);p.remove("commandFence");assertThrows(IllegalArgumentException.class,()->pump.receive("smartfarm/FARM001/PUMP01/status",mapper.writeValueAsBytes(p)));for(String key:List.of("circuitId","zoneId","controllerId","valveId","circuitRevision","zoneRevision")){var r=(ObjectNode)mapper.valueToTree(route);r.remove(key);assertThrows(IllegalArgumentException.class,()->PumpCircuitRoute.parse(r));}var r=(ObjectNode)mapper.valueToTree(route);r.put("circuitRevision",true);assertThrows(IllegalArgumentException.class,()->PumpCircuitRoute.parse(r));r.put("circuitRevision",1).put("extra",1);assertThrows(IllegalArgumentException.class,()->PumpCircuitRoute.parse(r));}
 @Test void onReportMustMatchDispatchedRoute()throws Exception{openValve();var c=start().command();reportPump(2,ordinal(c.commandId()),"ON",route);assertEquals("ON",pump.status().reportedState());assertThrows(IllegalArgumentException.class,()->reportPump(3,ordinal(c.commandId()),"ON",PumpCircuitRoute.from(circuits.find("PR2"))));}
 @Test void pumpRunBlocksAllValveMovementsAndEditsUntilOffStatus()throws Exception{openValve();var c=start().command();assertThrows(ResponseStatusException.class,()->valves.create("PR2",vrequest("PR2","OPEN")));assertThrows(ResponseStatusException.class,()->valves.create("PR1",vrequest("PR1","CLOSE")));assertThrows(ResponseStatusException.class,()->circuits.update("PR2",mapper.valueToTree(circuits.find("PR2"))));var off=fencing.createHttp(request("OFF",null,null),()->{}).command();jdbc.update("UPDATE pump_command SET state='EXECUTED' WHERE command_id IN (?,?)",c.commandId(),off.commandId());reportPump(3,ordinal(off.commandId()),"OFF",route);assertEquals("SENT",valves.create("PR1",vrequest("PR1","CLOSE")).state());}
 @Test void offWorksWithStaleOrMissingCircuitAndOfflineTransport()throws Exception{jdbc.update("DELETE FROM pump_status");when(transport.controlConnected()).thenReturn(false);var c=fencing.createHttp(request("OFF",null,null),()->{}).command();assertEquals("FAILED",c.state());assertEquals("MQTT_UNAVAILABLE",c.errorCode());assertNull(fencing.lookupHttp(c.commandId()).request().route());}
 @Test void shortenedExpiryFitsValveWindowAndInsufficientWindowRejects()throws Exception{var v=openValve();jdbc.update("UPDATE circuit_demo_command SET issued_at=CURRENT_TIMESTAMP-INTERVAL '15 seconds',expires_at=CURRENT_TIMESTAMP-INTERVAL '5 seconds' WHERE command_id=?",v.commandId());var c=start().command();assertTrue(Duration.between(c.issuedAt(),c.expiresAt()).getSeconds()<10);assertTrue(c.expiresAt().plusSeconds(7).isBefore(v.issuedAt().plusSeconds(30)));}
 @Test void tooLongDurationOrSpentValveWindowCannotReserve()throws Exception{var v=openValve();assertThrows(ResponseStatusException.class,()->fencing.createHttp(request("ON",31,route),()->{}));jdbc.update("UPDATE circuit_demo_command SET issued_at=CURRENT_TIMESTAMP-INTERVAL '27 seconds',expires_at=CURRENT_TIMESTAMP-INTERVAL '17 seconds' WHERE command_id=?",v.commandId());assertThrows(ResponseStatusException.class,this::start);assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM pump_command",Integer.class));}
 @Test void uncertainPublishRetainsRouteAndOffStillAvailable()throws Exception{openValve();doThrow(new IllegalStateException()).when(transport).publishCommand(any());var r=request("ON",5,route);assertEquals("PUBLISH_UNCERTAIN",fencing.createHttp(r,()->{}).command().state());assertEquals(route,fencing.lookupHttp(r.requestId()).request().route());fencing.createHttp(r,()->{});verify(transport,times(1)).publishCommand(any());assertThrows(ResponseStatusException.class,this::start);}
 @Test void resetRequiresSameRouteAndOpenContactsButDoesNotStart()throws Exception{openValve();jdbc.update("UPDATE pump_status SET safety_lockout=true,valve_interlock=jsonb_set(valve_interlock,'{fault}','\"VALVE_PROOF_LOST\"')");assertTrue(proof.snapshot("PR1").readyToReset());assertFalse(proof.snapshot("PR1").readyToStart());var c=fencing.createHttp(request("RESET_LOCKOUT",null,route),()->{});assertEquals("RESET_LOCKOUT",c.command().action());assertThrows(ResponseStatusException.class,this::start);}
 @Test void changedRouteForSameRequestConflicts()throws Exception{openValve();var r=request("ON",5,route);fencing.createHttp(r,()->{});var other=new PumpCommandFencing.HttpIntent(r.requestId(),r.action(),r.durationSeconds(),r.expectedBootId(),r.intentRevision(),r.reviewedAt(),PumpCircuitRoute.from(circuits.find("PR2")));assertThrows(ResponseStatusException.class,()->fencing.createHttp(other,()->{}));}
 @Test void preflightHttpIsReadonlyAndDoesNotRejuvenatePackets()throws Exception{openValve();String before=jdbc.queryForObject("SELECT row_to_json(p)::text FROM pump_status p",String.class);mvc.perform(get("/api/v1/irrigation-circuits/PR1/pump-proof")).andExpect(status().isOk()).andExpect(jsonPath("$.readyToStart").value(true)).andExpect(jsonPath("$.route.circuitId").value("PR1"));assertEquals(before,jdbc.queryForObject("SELECT row_to_json(p)::text FROM pump_status p",String.class));assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM pump_command",Integer.class));verify(transport,never()).publishCommand(any());}
 @Autowired org.springframework.beans.factory.ObjectProvider<CommandTransport> providers;@Autowired org.springframework.transaction.PlatformTransactionManager manager;
 @Test void advertisedRouteBlocksGenericEvenWhenRequirementFlagOff()throws Exception{openValve();var optional=new PumpCommandFencing(jdbc,mapper,providers,manager,true,true,false,true);optional.invalidateHttpOnStartup();assertThrows(ResponseStatusException.class,()->optional.createHttp(request("ON",5,null),()->{}));assertEquals("SENT",optional.createHttp(request("ON",5,route),()->{}).command().state());}
 @Test void requiredRouteCannotUseUnboundNewBoot()throws Exception{var p=pumpPacket(2,0,"OFF",null).put("bootId",UUID.randomUUID().toString());pump.receive("smartfarm/FARM001/PUMP01/status",mapper.writeValueAsBytes(p));openValve();assertThrows(ResponseStatusException.class,()->fencing.createHttp(new PumpCommandFencing.HttpIntent(UUID.randomUUID(),"ON",5,fencing.view().intent().bootId(),fencing.view().intent().revision(),Instant.now(),route),()->{}));}
 @Test void addingNewCircuitCannotChangeRoutingWhilePumpUnresolved()throws Exception{openValve();start();var c=(ObjectNode)mapper.valueToTree(circuits.find("PR2"));c.remove("revision");c.put("circuitId","PRNEW").put("controllerId","IRRIGATION80").put("valveId","VALVE80");assertThrows(ResponseStatusException.class,()->circuits.create(c));}

 @Test void legacyPumpWithoutProofReturnsDiagnosticInsteadOfServerError()throws Exception{jdbc.update("UPDATE pump_status SET valve_interlock=NULL");assertEquals("PUMP_PROOF_MISSING",proof.snapshot("PR1").reason());mvc.perform(get("/api/v1/irrigation-circuits/PR1/pump-proof")).andExpect(status().isOk()).andExpect(jsonPath("$.readyToStart").value(false));}

}
